    fn match_call_indirect_i32_add_loop(
        code: &[u8],
        mut ip: usize,
    ) -> Option<(u16, i32, Option<u16>, u16, u16, usize)> {
        if Self::decode_op_at(code, &mut ip)? != Op::LOCAL_GET {
            return None;
        }
        let acc_slot = Self::decode_u16_at(code, &mut ip)?;
        let elem_slot;
        let elem_index;
        match Self::decode_op_at(code, &mut ip)? {
            Op::I32_CONST => {
                elem_index = Self::decode_leb_i32_at(code, &mut ip)?;
                elem_slot = None;
            }
            Op::LOCAL_GET => {
                elem_slot = Some(Self::decode_u16_at(code, &mut ip)?);
                elem_index = 0;
            }
            _ => return None,
        }
        let call_ip = ip;
        if Self::decode_op_at(code, &mut ip)? != Op::CALL_INDIRECT {
            return None;
        }
        if *code.get(ip)? != 1 || *code.get(ip + 2)? != 1 {
            return None;
        }
        let tableidx = *code.get(ip + 1)? as u16;
        ip += 3;
        if Self::decode_op_at(code, &mut ip)? != Op::LOCAL_SET {
            return None;
        }
        if Self::decode_u16_at(code, &mut ip)? != acc_slot {
            return None;
        }
        if Self::decode_op_at(code, &mut ip)? != Op::LOCAL_GET {
            return None;
        }
        let counter_slot = Self::decode_u16_at(code, &mut ip)?;
        if elem_slot == Some(acc_slot) || elem_slot == Some(counter_slot) {
            return None;
        }
        if Self::decode_op_at(code, &mut ip)? != Op::I32_CONST {
            return None;
        }
        if Self::decode_leb_i32_at(code, &mut ip)? != 1 {
            return None;
        }
        if Self::decode_op_at(code, &mut ip)? != Op::I32_SUB {
            return None;
        }
        if Self::decode_op_at(code, &mut ip)? != Op::LOCAL_TEE {
            return None;
        }
        if Self::decode_u16_at(code, &mut ip)? != counter_slot {
            return None;
        }
        if Self::decode_op_at(code, &mut ip)? != Op::BR_IF {
            return None;
        }
        if Self::decode_leb_u32_at(code, &mut ip)? != 0 {
            return None;
        }
        if Self::decode_op_at(code, &mut ip)? != Op::END {
            return None;
        }
        Some((tableidx, elem_index, elem_slot, acc_slot, counter_slot, call_ip,))
    }

    fn match_global_get_local_loop(code: &[u8], mut ip: usize) -> Option<(u32, u16, u16)> {
        if Self::decode_op_at(code, &mut ip)? != Op::GLOBAL_GET {
            return None;
        }
        if ip + 3 >= code.len() {
            return None;
        }
        let global_idx = ((code[ip] as u32) << 24)
            | ((code[ip + 1] as u32) << 16)
            | ((code[ip + 2] as u32) << 8)
            | code[ip + 3] as u32;
        ip += 4;
        if Self::decode_op_at(code, &mut ip)? != Op::LOCAL_SET {
            return None;
        }
        let dst_slot = Self::decode_u16_at(code, &mut ip)?;
        if Self::decode_op_at(code, &mut ip)? != Op::LOCAL_GET {
            return None;
        }
        let counter_slot = Self::decode_u16_at(code, &mut ip)?;
        if dst_slot == counter_slot {
            return None;
        }
        if Self::decode_op_at(code, &mut ip)? != Op::I32_CONST {
            return None;
        }
        if Self::decode_leb_i32_at(code, &mut ip)? != 1 {
            return None;
        }
        if Self::decode_op_at(code, &mut ip)? != Op::I32_SUB {
            return None;
        }
        if Self::decode_op_at(code, &mut ip)? != Op::LOCAL_TEE {
            return None;
        }
        if Self::decode_u16_at(code, &mut ip)? != counter_slot {
            return None;
        }
        if Self::decode_op_at(code, &mut ip)? != Op::BR_IF {
            return None;
        }
        if Self::decode_leb_u32_at(code, &mut ip)? != 0 {
            return None;
        }
        if Self::decode_op_at(code, &mut ip)? != Op::END {
            return None;
        }
        Some((global_idx, dst_slot, counter_slot))
    }

