    fn try_managed_array_to_linear_loop(
        &mut self,
        arr_slot: u16,
        dst_slot: u16,
        len_slot: u16,
        i_slot: u16,
        byte_slot: u16,
        mask: i32,
    ) -> Result<bool, VMError> {
        let frame_index = self.frames.len() - 1;
        let base = self.frames[frame_index].base;
        let len = self.stack_i32_at(base + len_slot as usize)? as u32;
        let start_i = self.stack_i32_at(base + i_slot as usize)? as u32;
        let count = len.saturating_sub(start_i) as usize;
        if count == 0 {
            if let Some(entry) = self.label_at_depth(1) {
                self.branch_to_label(1, entry);
                return Ok(true);
            }
            return Ok(false);
        }
        let arr = self
            .stack
            .get(base + arr_slot as usize)
            .cloned()
            .ok_or_else(|| VMError::new("trap: local index out of bounds"))?;
        let dst = self.stack_i32_at(base + dst_slot as usize)?;
        let start_addr = dst.wrapping_add(start_i as i32) as usize;
        let Value::Object(obj) = arr else {
            return Ok(false);
        };
        let type_id = {
            let ob = obj.lock().unwrap();
            match &ob.kind {
                ObjectKind::Array(_) => {}
                ObjectKind::TypedArray(ta)
                    if matches!(
                        ta.elem,
                        TypedElemKind::I8 | TypedElemKind::U8 | TypedElemKind::U8Clamped
                    ) => {}
                _ => return Ok(false),
            }
            ob.type_id
        };
        let is_gc = type_id > 0
            && self
                .type_registry
                .get(type_id)
                .is_some_and(|td| td.is_array());
        if count != 0 {
            if let Some(result) = self.memory.with_buffer_mut_exclusive(|memory| {
                if start_addr
                    .checked_add(count)
                    .map_or(true, |end| end > memory.len())
                {
                    return Ok::<Option<Value>, VMError>(None);
                }
                let ob = obj.lock().unwrap();
                let ObjectKind::Array(values) = &ob.kind else {
                    return Ok::<Option<Value>, VMError>(None);
                };
                let start_idx = start_i as usize;
                let mask_u = mask as u32;
                let contiguous = count > 0
                    && start_idx
                        .checked_add(count)
                        .is_some_and(|end| end <= values.len())
                    && start_i
                        .checked_add((count - 1) as u32)
                        .is_some_and(|last| {
                            let required = if last == 0 {
                                0
                            } else {
                                last.checked_add(1).and_then(u32::checked_next_power_of_two).map(|n| n - 1).unwrap_or(u32::MAX)
                            };
                            (mask_u & required) == required
                });
                if contiguous {
                    let src = &values[start_idx..start_idx + count];
                    for (slot, value) in memory[start_addr..start_addr + count]
                        .iter_mut()
                        .zip(src)
                    {
                        *slot = value_to_i32_byte(value);
                    }
                    return Ok(src.last().cloned());
                }
                if mask >= 0 && (mask_u as usize) < values.len() {
                    let dst = &mut memory[start_addr..start_addr + count];
                    if let Some(last) =
                        copy_power2_masked_values_to_bytes(dst, values, start_i, mask_u)
                    {
                        return Ok(Some(last));
                    }
                    let mut i = start_i;
                    for slot in dst {
                        let idx = (i & mask_u) as usize;
                        *slot = value_to_i32_byte(unsafe { values.get_unchecked(idx) });
                        i = i.wrapping_add(1);
                    }
                    let last_idx = (start_i.wrapping_add((count - 1) as u32) & mask_u) as usize;
                    return Ok(Some(unsafe { values.get_unchecked(last_idx) }.clone()));
                }
                if is_gc {
                    let mut i = start_i;
                    for _ in 0..count {
                        let idx = (i as i32 & mask) as usize;
                        if idx >= values.len() {
                            return Ok(None);
                        }
                        i = i.wrapping_add(1);
                    }
                }
                let mut last_idx = None;
                let mut last_missing = false;
                let mut i = start_i;
                for offset in 0..count {
                    let idx = (i as i32 & mask) as usize;
                    if let Some(value) = values.get(idx) {
                        memory[start_addr + offset] = value_to_i32_byte(value);
                        last_idx = Some(idx);
                        last_missing = false;
                    } else {
                        memory[start_addr + offset] = 0;
                        last_idx = None;
                        last_missing = true;
                    }
                    i = i.wrapping_add(1);
                }
                let last = if last_missing {
                    Some(Value::Undefined)
                } else {
                    last_idx.and_then(|idx| values.get(idx).cloned())
                };
                Ok(last)
            }) {
                let Some(last_value) = result? else {
                    return Ok(false);
                };
                let byte_idx = base + byte_slot as usize;
                if byte_idx >= self.stack.len() {
                    self.stack.resize(byte_idx + 1, Value::Null);
                }
                self.stack[byte_idx] = last_value;
                self.stack[base + i_slot as usize] = Value::I32(len as i32);
                if let Some(counters) = self.perf_counters.as_mut() {
                    let n = count as u64;
                    counters.super_managed_to_linear =
                        counters.super_managed_to_linear.saturating_add(1);
                    counters.array_get = counters.array_get.saturating_add(n);
                    counters.array_get_dense = counters.array_get_dense.saturating_add(n);
                    counters.i32_store8 = counters.i32_store8.saturating_add(n);
                }
                if let Some(entry) = self.label_at_depth(1) {
                    self.branch_to_label(1, entry);
                    return Ok(true);
                }
                return Ok(false);
            }
        }
        if let Some(counters) = self.perf_counters.as_mut() {
            counters.record_object_lock();
        }
        let last_value = self.memory.with_buffer_mut(|memory| {
            let Some(end) = start_addr
                .checked_add(count)
                .filter(|&end| end <= memory.len())
            else {
                return Ok::<Option<Value>, VMError>(None);
            };
            let ob = obj.lock().unwrap();
            let ObjectKind::Array(values) = &ob.kind else {
                return Ok::<Option<Value>, VMError>(None);
            };
            let start_idx = start_i as usize;
            let mask_u = mask as u32;
            let contiguous = count > 0
                && start_idx
                    .checked_add(count)
                    .is_some_and(|end| end <= values.len())
                && start_i
                    .checked_add((count - 1) as u32)
                    .is_some_and(|last| {
                        let required = if last == 0 {
                            0
                        } else {
                            last.checked_add(1).and_then(u32::checked_next_power_of_two).map(|n| n - 1).unwrap_or(u32::MAX)
                        };
                        (mask_u & required) == required
            });
            if contiguous {
                let src = &values[start_idx..start_idx + count];
                for (slot, value) in memory[start_addr..end].iter_mut().zip(src) {
                    *slot = value_to_i32_byte(value);
                }
                return Ok(src.last().cloned());
            }
            if mask >= 0 && (mask_u as usize) < values.len() {
                let dst = &mut memory[start_addr..end];
                if let Some(last) =
                    copy_power2_masked_values_to_bytes(dst, values, start_i, mask_u)
                {
                    return Ok(Some(last));
                }
                let mut i = start_i;
                for slot in dst {
                    let idx = (i & mask_u) as usize;
                    *slot = value_to_i32_byte(unsafe { values.get_unchecked(idx) });
                    i = i.wrapping_add(1);
                }
                let last_idx = (start_i.wrapping_add((count - 1) as u32) & mask_u) as usize;
                return Ok(Some(unsafe { values.get_unchecked(last_idx) }.clone()));
            }
            let mut last_idx = None;
            let mut last_missing = false;
            let mut i = start_i;
            for slot in &mut memory[start_addr..end] {
                let idx = (i as i32 & mask) as usize;
                if let Some(value) = values.get(idx) {
                    *slot = value_to_i32_byte(value);
                    last_idx = Some(idx);
                    last_missing = false;
                } else if is_gc {
                    return Ok(None);
                } else {
                    *slot = 0;
                    last_idx = None;
                    last_missing = true;
                }
                i = i.wrapping_add(1);
            }
            let last = if last_missing {
                Some(Value::Undefined)
            } else {
                last_idx.and_then(|idx| values.get(idx).cloned())
            };
            Ok(last)
        })?;
        let Some(last_value) = last_value else {
            return Ok(false);
        };
        let byte_idx = base + byte_slot as usize;
        if byte_idx >= self.stack.len() {
            self.stack.resize(byte_idx + 1, Value::Null);
        }
        self.stack[byte_idx] = last_value;
        self.stack[base + i_slot as usize] = Value::I32(if start_i < len {
            len as i32
        } else {
            start_i as i32
        });
        if let Some(counters) = self.perf_counters.as_mut() {
            let n = count as u64;
            counters.super_managed_to_linear = counters.super_managed_to_linear.saturating_add(1);
            counters.array_get = counters.array_get.saturating_add(n);
            counters.array_get_dense = counters.array_get_dense.saturating_add(n);
            counters.i32_store8 = counters.i32_store8.saturating_add(n);
        }
        if let Some(entry) = self.label_at_depth(1) {
            self.branch_to_label(1, entry);
            return Ok(true);
        }
        Ok(false)
    }

    fn try_managed_array_offset_to_linear_loop(
        &mut self,
        arr_slot: u16,
        src_offset_slot: u16,
        dst_slot: u16,
        len_slot: u16,
        i_slot: u16,
        byte_slot: u16,
        store_value_slot: Option<u16>,
        store_addr_slot: Option<u16>,
    ) -> Result<bool, VMError> {
        let frame_index = self.frames.len() - 1;
        let base = self.frames[frame_index].base;
        let len = self.stack_i32_at(base + len_slot as usize)? as u32;
        let start_i = self.stack_i32_at(base + i_slot as usize)? as u32;
        let count = len.saturating_sub(start_i) as usize;
        if count == 0 {
            if let Some(entry) = self.label_at_depth(1) {
                self.branch_to_label(1, entry);
                return Ok(true);
            }
            return Ok(false);
        }
        let arr = self
            .stack
            .get(base + arr_slot as usize)
            .cloned()
            .ok_or_else(|| VMError::new("trap: local index out of bounds"))?;
        let src_offset_raw = self.stack_i32_at(base + src_offset_slot as usize)?;
        if src_offset_raw < 0 {
            return Ok(false);
        }
        let Some(src_start_u32) = (src_offset_raw as u32).checked_add(start_i) else {
            return Ok(false);
        };
        let dst = self.stack_i32_at(base + dst_slot as usize)?;
        let start_addr = dst.wrapping_add(start_i as i32) as usize;
        let Value::Object(obj) = arr else {
            return Ok(false);
        };
        let type_id = {
            let ob = obj.lock().unwrap();
            match &ob.kind {
                ObjectKind::Array(_) => {}
                ObjectKind::TypedArray(ta)
                    if matches!(
                        ta.elem,
                        TypedElemKind::I8 | TypedElemKind::U8 | TypedElemKind::U8Clamped
                    ) => {}
                _ => return Ok(false),
            }
            ob.type_id
        };
        let is_gc = type_id > 0
            && self
                .type_registry
                .get(type_id)
                .is_some_and(|td| td.is_array());
        if type_id != 0 && !is_gc {
            return Ok(false);
        }

        let last_value = if let Some(result) = self.memory.with_buffer_mut_exclusive(|memory| {
            copy_offset_source_to_linear_bytes(
                memory.as_mut_slice(),
                &obj,
                start_addr,
                count,
                src_start_u32,
            )
        }) {
            result?
        } else {
            self.memory.with_buffer_mut(|memory| {
                copy_offset_source_to_linear_bytes(
                    memory.as_mut_slice(),
                    &obj,
                    start_addr,
                    count,
                    src_start_u32,
                )
            })?
        };
        let Some(last_value) = last_value else {
            return Ok(false);
        };

        let last_addr = dst.wrapping_add((len - 1) as i32);
        let byte_idx = base + byte_slot as usize;
        let mut required_len = byte_idx + 1;
        if let Some(slot) = store_value_slot {
            required_len = required_len.max(base + slot as usize + 1);
        }
        if let Some(slot) = store_addr_slot {
            required_len = required_len.max(base + slot as usize + 1);
        }
        if required_len > self.stack.len() {
            self.stack.resize(required_len, Value::Null);
        }
        self.stack[byte_idx] = last_value.clone();
        if let Some(slot) = store_value_slot {
            self.stack[base + slot as usize] = last_value;
        }
        if let Some(slot) = store_addr_slot {
            self.stack[base + slot as usize] = Value::I32(last_addr);
        }
        self.stack[base + i_slot as usize] = Value::I32(len as i32);
        if let Some(counters) = self.perf_counters.as_mut() {
            let n = count as u64;
            counters.super_managed_to_linear = counters.super_managed_to_linear.saturating_add(1);
            counters.array_get = counters.array_get.saturating_add(n);
            counters.array_get_dense = counters.array_get_dense.saturating_add(n);
            counters.i32_store8 = counters.i32_store8.saturating_add(n);
        }
        if let Some(entry) = self.label_at_depth(1) {
            self.branch_to_label(1, entry);
            return Ok(true);
        }
        Ok(false)
    }

    fn try_linear_to_managed_array_loop(
        &mut self,
        arr_slot: u16,
        src_slot: u16,
        len_slot: u16,
        i_slot: u16,
        byte_slot: u16,
        mask: i32,
    ) -> Result<bool, VMError> {
        let frame_index = self.frames.len() - 1;
        let base = self.frames[frame_index].base;
        let len = self.stack_i32_at(base + len_slot as usize)? as u32;
        let start_i = self.stack_i32_at(base + i_slot as usize)? as u32;
        let count = len.saturating_sub(start_i) as usize;
        if count == 0 {
            if let Some(entry) = self.label_at_depth(1) {
                self.branch_to_label(1, entry);
                return Ok(true);
            }
            return Ok(false);
        }
        let arr = self
            .stack
            .get(base + arr_slot as usize)
            .cloned()
            .ok_or_else(|| VMError::new("trap: local index out of bounds"))?;
        let src = self.stack_i32_at(base + src_slot as usize)?;
        let start_addr = src.wrapping_add(start_i as i32) as usize;
        let Value::Object(obj) = arr else {
            return Ok(false);
        };
        let (type_id, has_setitem) = {
            let ob = obj.lock().unwrap();
            if !matches!(ob.kind, ObjectKind::Array(_)) {
                return Ok(false);
            }
            (ob.type_id, ob.properties.contains_key("__setitem__"))
        };
        let is_gc = type_id > 0
            && self
                .type_registry
                .get(type_id)
                .is_some_and(|td| td.is_array());
        if type_id != 0 && !is_gc {
            return Ok(false);
        }
        if !is_gc && has_setitem {
            return Ok(false);
        }
        if count != 0 {
            if let Some(result) = self.memory.with_buffer_mut_exclusive(|memory| {
                if start_addr
                    .checked_add(count)
                    .map_or(true, |end| end > memory.len())
                {
                    return Ok::<Option<(Option<Value>, usize)>, VMError>(None);
                }
                let mut ob = obj.lock().unwrap();
                let (last, new_len) = {
                    let ObjectKind::Array(values) = &mut ob.kind else {
                        return Ok::<Option<(Option<Value>, usize)>, VMError>(None);
                    };
                    let start_idx = start_i as usize;
                    let mask_u = mask as u32;
                    let contiguous = start_idx
                        .checked_add(count)
                        .is_some_and(|end_idx| !is_gc || end_idx <= values.len())
                        && start_i
                            .checked_add((count - 1) as u32)
                            .is_some_and(|last| {
                                let required = if last == 0 {
                                    0
                                } else {
                                    last.checked_add(1).and_then(u32::checked_next_power_of_two).map(|n| n - 1).unwrap_or(u32::MAX)
                                };
                                (mask_u & required) == required
                            });
                    if contiguous {
                        let end_idx = start_idx + count;
                        if end_idx > values.len() {
                            values.resize(end_idx, Value::Null);
                        }
                        let src = &memory[start_addr..start_addr + count];
                        for (slot, byte) in values[start_idx..end_idx].iter_mut().zip(src) {
                            *slot = Value::I32(*byte as i32);
                        }
                        let last = src.last().copied().map(|byte| Value::I32(byte as i32));
                        return Ok(Some((last, values.len())));
                    }
                    if mask >= 0 && (mask_u as usize) < values.len() {
                        let src = &memory[start_addr..start_addr + count];
                        if let Some(last) =
                            copy_final_power2_period_bytes_to_values(values, src, start_i, mask_u)
                        {
                            return Ok(Some((Some(last), values.len())));
                        }
                        let mut i = start_i;
                        for byte in src.iter().copied() {
                            let idx = (i & mask_u) as usize;
                            unsafe {
                                *values.get_unchecked_mut(idx) = Value::I32(byte as i32);
                            }
                            i = i.wrapping_add(1);
                        }
                        let last = src.last().copied().map(|byte| Value::I32(byte as i32));
                        return Ok(Some((last, values.len())));
                    }
                    if is_gc {
                        for offset in 0..count {
                            let i = start_i.wrapping_add(offset as u32);
                            let idx = (i as i32 & mask) as usize;
                            if idx >= values.len() {
                                return Ok(None);
                            }
                        }
                    }
                    let mut last_byte = None;
                    for offset in 0..count {
                        let i = start_i.wrapping_add(offset as u32);
                        let idx = (i as i32 & mask) as usize;
                        let byte = memory[start_addr + offset];
                        if idx >= values.len() {
                            values.resize(idx + 1, Value::Null);
                        }
                        values[idx] = Value::I32(byte as i32);
                        last_byte = Some(byte);
                    }
                    (last_byte.map(|byte| Value::I32(byte as i32)), values.len())
                };
                if !is_gc {
                    ob.properties
                        .insert("length".into(), Value::F64(new_len as f64));
                }
                Ok(Some((last, new_len)))
            }) {
                let Some((last_value, _new_len)) = result? else {
                    return Ok(false);
                };
                if let Some(value) = last_value {
                    let byte_idx = base + byte_slot as usize;
                    if byte_idx >= self.stack.len() {
                        self.stack.resize(byte_idx + 1, Value::Null);
                    }
                    self.stack[byte_idx] = value;
                }
                self.stack[base + i_slot as usize] = Value::I32(len as i32);
                if let Some(counters) = self.perf_counters.as_mut() {
                    let n = count as u64;
                    counters.super_linear_to_managed =
                        counters.super_linear_to_managed.saturating_add(1);
                    counters.i32_load8_u = counters.i32_load8_u.saturating_add(n);
                    counters.array_set = counters.array_set.saturating_add(n);
                    counters.array_set_dense = counters.array_set_dense.saturating_add(n);
                }
                if let Some(entry) = self.label_at_depth(1) {
                    self.branch_to_label(1, entry);
                    return Ok(true);
                }
                return Ok(false);
            }
        }
        if let Some(counters) = self.perf_counters.as_mut() {
            counters.record_object_lock();
        }
        let last_value = self.memory.with_buffer(|memory| {
            let Some(end) = start_addr
                .checked_add(count)
                .filter(|&end| end <= memory.len())
            else {
                return Ok::<Option<Value>, VMError>(None);
            };
            let mut ob = obj.lock().unwrap();
            let (last, new_len) = {
                let ObjectKind::Array(values) = &mut ob.kind else {
                    return Ok::<Option<Value>, VMError>(None);
                };
                let start_idx = start_i as usize;
                let mask_u = mask as u32;
                let contiguous = start_idx
                    .checked_add(count)
                    .is_some_and(|end_idx| !is_gc || end_idx <= values.len())
                    && start_i
                        .checked_add((count - 1) as u32)
                        .is_some_and(|last| {
                            let required = if last == 0 {
                                0
                            } else {
                                last.checked_add(1).and_then(u32::checked_next_power_of_two).map(|n| n - 1).unwrap_or(u32::MAX)
                            };
                            (mask_u & required) == required
                        });
                if contiguous {
                    let end_idx = start_idx + count;
                    if end_idx > values.len() {
                        values.resize(end_idx, Value::Null);
                    }
                    let src = &memory[start_addr..end];
                    for (slot, byte) in values[start_idx..end_idx].iter_mut().zip(src) {
                        *slot = Value::I32(*byte as i32);
                    }
                    let last = src.last().copied().map(|byte| Value::I32(byte as i32));
                    return Ok(last);
                }
                if mask >= 0 && (mask_u as usize) < values.len() {
                    let src = &memory[start_addr..end];
                    if let Some(last) =
                        copy_final_power2_period_bytes_to_values(values, src, start_i, mask_u)
                    {
                        return Ok(Some(last));
                    }
                    let mut i = start_i;
                    for byte in src.iter().copied() {
                        let idx = (i & mask_u) as usize;
                        unsafe {
                            *values.get_unchecked_mut(idx) = Value::I32(byte as i32);
                        }
                        i = i.wrapping_add(1);
                    }
                    return Ok(src.last().copied().map(|byte| Value::I32(byte as i32)));
                }
                if is_gc {
                    for offset in 0..count {
                        let i = start_i.wrapping_add(offset as u32);
                        let idx = (i as i32 & mask) as usize;
                        if idx >= values.len() {
                            return Ok(None);
                        }
                    }
                }
                let mut last_byte = None;
                for (offset, byte) in memory[start_addr..end].iter().copied().enumerate() {
                    let i = start_i.wrapping_add(offset as u32);
                    let idx = (i as i32 & mask) as usize;
                    if idx >= values.len() {
                        values.resize(idx + 1, Value::Null);
                    }
                    values[idx] = Value::I32(byte as i32);
                    last_byte = Some(byte);
                }
                (last_byte.map(|byte| Value::I32(byte as i32)), values.len())
            };
            if !is_gc {
                ob.properties
                    .insert("length".into(), Value::F64(new_len as f64));
            }
            Ok(last)
        })?;
        let Some(last_value) = last_value else {
            return Ok(false);
        };
        let byte_idx = base + byte_slot as usize;
        if byte_idx >= self.stack.len() {
            self.stack.resize(byte_idx + 1, Value::Null);
        }
        self.stack[byte_idx] = last_value;
        self.stack[base + i_slot as usize] = Value::I32(if start_i < len {
            len as i32
        } else {
            start_i as i32
        });
        if let Some(counters) = self.perf_counters.as_mut() {
            let n = count as u64;
            counters.super_linear_to_managed = counters.super_linear_to_managed.saturating_add(1);
            counters.i32_load8_u = counters.i32_load8_u.saturating_add(n);
            counters.array_set = counters.array_set.saturating_add(n);
            counters.array_set_dense = counters.array_set_dense.saturating_add(n);
        }
        if let Some(entry) = self.label_at_depth(1) {
            self.branch_to_label(1, entry);
            return Ok(true);
        }
        Ok(false)
    }

    fn try_linear_to_managed_array_offset_loop(
        &mut self,
        arr_slot: u16,
        dst_offset_slot: u16,
        src_slot: u16,
        len_slot: u16,
        i_slot: u16,
        byte_slot: u16,
    ) -> Result<bool, VMError> {
        let frame_index = self.frames.len() - 1;
        let base = self.frames[frame_index].base;
        let len = self.stack_i32_at(base + len_slot as usize)? as u32;
        let start_i = self.stack_i32_at(base + i_slot as usize)? as u32;
        let count = len.saturating_sub(start_i) as usize;
        if count == 0 {
            if let Some(entry) = self.label_at_depth(1) {
                self.branch_to_label(1, entry);
                return Ok(true);
            }
            return Ok(false);
        }
        let arr = self
            .stack
            .get(base + arr_slot as usize)
            .cloned()
            .ok_or_else(|| VMError::new("trap: local index out of bounds"))?;
        let dst_offset_raw = self.stack_i32_at(base + dst_offset_slot as usize)?;
        if dst_offset_raw < 0 {
            return Ok(false);
        }
        let Some(dst_start_u32) = (dst_offset_raw as u32).checked_add(start_i) else {
            return Ok(false);
        };
        let src = self.stack_i32_at(base + src_slot as usize)?;
        let start_addr = src.wrapping_add(start_i as i32) as usize;
        let Value::Object(obj) = arr else {
            return Ok(false);
        };
        let (type_id, has_setitem) = {
            let ob = obj.lock().unwrap();
            if !matches!(ob.kind, ObjectKind::Array(_)) {
                return Ok(false);
            }
            (ob.type_id, ob.properties.contains_key("__setitem__"))
        };
        let is_gc = type_id > 0
            && self
                .type_registry
                .get(type_id)
                .is_some_and(|td| td.is_array());
        if type_id != 0 && !is_gc {
            return Ok(false);
        }
        if !is_gc && has_setitem {
            return Ok(false);
        }

        if let Some(result) = self.memory.with_buffer_mut_exclusive(|memory| {
            let Some(end) = start_addr
                .checked_add(count)
                .filter(|&end| end <= memory.len())
            else {
                return Ok::<Option<(Value, usize)>, VMError>(None);
            };
            let mut ob = obj.lock().unwrap();
            let (last, new_len) = {
                let ObjectKind::Array(values) = &mut ob.kind else {
                    return Ok::<Option<(Value, usize)>, VMError>(None);
                };
                let dst_start = dst_start_u32 as usize;
                let Some(dst_end) = dst_start.checked_add(count) else {
                    return Ok(None);
                };
                if is_gc {
                    if dst_end > values.len() {
                        return Ok(None);
                    }
                } else if dst_end > values.len() {
                    values.resize(dst_end, Value::Null);
                }
                let src_bytes = &memory[start_addr..end];
                for (slot, byte) in values[dst_start..dst_end].iter_mut().zip(src_bytes) {
                    *slot = Value::I32(*byte as i32);
                }
                let last = Value::I32(unsafe { *src_bytes.get_unchecked(src_bytes.len() - 1) } as i32);
                (last, values.len())
            };
            if !is_gc {
                ob.properties
                    .insert("length".into(), Value::F64(new_len as f64));
            }
            Ok(Some((last, new_len)))
        }) {
            let Some((last_value, _new_len)) = result? else {
                return Ok(false);
            };
            let byte_idx = base + byte_slot as usize;
            if byte_idx >= self.stack.len() {
                self.stack.resize(byte_idx + 1, Value::Null);
            }
            self.stack[byte_idx] = last_value;
            self.stack[base + i_slot as usize] = Value::I32(len as i32);
            if let Some(counters) = self.perf_counters.as_mut() {
                let n = count as u64;
                counters.super_linear_to_managed =
                    counters.super_linear_to_managed.saturating_add(1);
                counters.i32_load8_u = counters.i32_load8_u.saturating_add(n);
                counters.array_set = counters.array_set.saturating_add(n);
                counters.array_set_dense = counters.array_set_dense.saturating_add(n);
            }
            if let Some(entry) = self.label_at_depth(1) {
                self.branch_to_label(1, entry);
                return Ok(true);
            }
            return Ok(false);
        }

        let last_value = self.with_memory_bytes(0, start_addr, count, |src_bytes| {
            let mut ob = obj.lock().unwrap();
            let (last, new_len) = {
                let ObjectKind::Array(values) = &mut ob.kind else {
                    return Ok::<Option<(Value, usize)>, VMError>(None);
                };
                let dst_start = dst_start_u32 as usize;
                let Some(dst_end) = dst_start.checked_add(count) else {
                    return Ok(None);
                };
                if is_gc {
                    if dst_end > values.len() {
                        return Ok(None);
                    }
                } else if dst_end > values.len() {
                    values.resize(dst_end, Value::Null);
                }
                for (slot, byte) in values[dst_start..dst_end].iter_mut().zip(src_bytes) {
                    *slot = Value::I32(*byte as i32);
                }
                let last = Value::I32(*src_bytes.last().unwrap_or(&0) as i32);
                (last, values.len())
            };
            if !is_gc {
                ob.properties
                    .insert("length".into(), Value::F64(new_len as f64));
            }
            Ok(Some((last, new_len)))
        })?;
        let Some((last_value, _new_len)) = last_value else {
            return Ok(false);
        };
        let byte_idx = base + byte_slot as usize;
        if byte_idx >= self.stack.len() {
            self.stack.resize(byte_idx + 1, Value::Null);
        }
        self.stack[byte_idx] = last_value;
        self.stack[base + i_slot as usize] = Value::I32(len as i32);
        if let Some(counters) = self.perf_counters.as_mut() {
            let n = count as u64;
            counters.super_linear_to_managed = counters.super_linear_to_managed.saturating_add(1);
            counters.i32_load8_u = counters.i32_load8_u.saturating_add(n);
            counters.array_set = counters.array_set.saturating_add(n);
            counters.array_set_dense = counters.array_set_dense.saturating_add(n);
        }
        if let Some(entry) = self.label_at_depth(1) {
            self.branch_to_label(1, entry);
            return Ok(true);
        }
        Ok(false)
    }

    fn try_linear_memory_copy_loop(
        &mut self,
        src_slot: u16,
        src_offset_slot: Option<u16>,
        dst_slot: u16,
        dst_offset_slot: Option<u16>,
        len_slot: u16,
        i_slot: u16,
        byte_slot: u16,
    ) -> Result<bool, VMError> {
        let frame_index = self.frames.len() - 1;
        let base = self.frames[frame_index].base;
        let len = self.stack_i32_at(base + len_slot as usize)? as u32;
        let start_i = self.stack_i32_at(base + i_slot as usize)? as u32;
        let count = len.saturating_sub(start_i) as usize;
        if count == 0 {
            if let Some(entry) = self.label_at_depth(1) {
                self.branch_to_label(1, entry);
                return Ok(true);
            }
            return Ok(false);
        }
        let src = self.stack_i32_at(base + src_slot as usize)?;
        let dst = self.stack_i32_at(base + dst_slot as usize)?;
        let src = if let Some(src_offset_slot) = src_offset_slot {
            let src_offset = self.stack_i32_at(base + src_offset_slot as usize)?;
            src.wrapping_add(src_offset)
        } else {
            src
        };
        let dst = if let Some(dst_offset_slot) = dst_offset_slot {
            let dst_offset = self.stack_i32_at(base + dst_offset_slot as usize)?;
            dst.wrapping_add(dst_offset)
        } else {
            dst
        };
        let src_addr = src.wrapping_add(start_i as i32) as usize;
        let dst_addr = dst.wrapping_add(start_i as i32) as usize;
        if count != 0 {
            let last = if let Some(result) = self.memory.with_buffer_mut_exclusive(|memory| {
                let Some(src_end) = src_addr
                    .checked_add(count)
                    .filter(|&end| end <= memory.len())
                else {
                    return Ok::<Option<u8>, VMError>(None);
                };
                if dst_addr
                    .checked_add(count)
                    .map_or(true, |end| end > memory.len())
                {
                    return Ok(None);
                }
                let last = memory[src_end - 1];
                memory.copy_within(src_addr..src_end, dst_addr);
                Ok(Some(last))
            }) {
                let Some(last) = result? else {
                    return Ok(false);
                };
                last
            } else {
                let Some(last) = self.memory.with_buffer_mut(|memory| {
                    let Some(src_end) = src_addr
                        .checked_add(count)
                        .filter(|&end| end <= memory.len())
                    else {
                        return Ok::<Option<u8>, VMError>(None);
                    };
                    if dst_addr
                        .checked_add(count)
                        .map_or(true, |end| end > memory.len())
                    {
                        return Ok(None);
                    }
                    let last = memory[src_end - 1];
                    memory.copy_within(src_addr..src_end, dst_addr);
                    Ok(Some(last))
                })?
                else {
                    return Ok(false);
                };
                last
            };
            let byte_idx = base + byte_slot as usize;
            if byte_idx >= self.stack.len() {
                self.stack.resize(byte_idx + 1, Value::Null);
            }
            self.stack[byte_idx] = Value::I32(last as i32);
        }
        self.stack[base + i_slot as usize] = Value::I32(if start_i < len {
            len as i32
        } else {
            start_i as i32
        });
        if let Some(counters) = self.perf_counters.as_mut() {
            let n = count as u64;
            counters.super_linear_copy = counters.super_linear_copy.saturating_add(1);
            counters.i32_load8_u = counters.i32_load8_u.saturating_add(n);
            counters.i32_store8 = counters.i32_store8.saturating_add(n);
            counters.memory_copy = counters.memory_copy.saturating_add(1);
            counters.memory_copy_bytes = counters.memory_copy_bytes.saturating_add(n);
        }
        if let Some(entry) = self.label_at_depth(1) {
            self.branch_to_label(1, entry);
            return Ok(true);
        }
        Ok(false)
    }

    fn try_linear_memory_i32_copy_loop(
        &mut self,
        src_slot: u16,
        src_offset_slot: Option<u16>,
        dst_slot: u16,
        dst_offset_slot: Option<u16>,
        len_slot: u16,
        i_slot: u16,
        value_slot: u16,
    ) -> Result<bool, VMError> {
        let frame_index = self.frames.len() - 1;
        let base = self.frames[frame_index].base;
        let len = self.stack_i32_at(base + len_slot as usize)? as u32;
        let start_i = self.stack_i32_at(base + i_slot as usize)? as u32;
        let remaining = len.saturating_sub(start_i) as usize;
        if remaining == 0 {
            if let Some(entry) = self.label_at_depth(1) {
                self.branch_to_label(1, entry);
                return Ok(true);
            }
            return Ok(false);
        }
        let iterations = (remaining + 3) / 4;
        let Some(copy_bytes) = iterations.checked_mul(4) else {
            return Ok(false);
        };
        let Some(final_i) = start_i.checked_add(copy_bytes as u32) else {
            return Ok(false);
        };
        let src = self.stack_i32_at(base + src_slot as usize)?;
        let dst = self.stack_i32_at(base + dst_slot as usize)?;
        let src = if let Some(src_offset_slot) = src_offset_slot {
            let src_offset = self.stack_i32_at(base + src_offset_slot as usize)?;
            src.wrapping_add(src_offset)
        } else {
            src
        };
        let dst = if let Some(dst_offset_slot) = dst_offset_slot {
            let dst_offset = self.stack_i32_at(base + dst_offset_slot as usize)?;
            dst.wrapping_add(dst_offset)
        } else {
            dst
        };
        let src_addr = src.wrapping_add(start_i as i32) as usize;
        let dst_addr = dst.wrapping_add(start_i as i32) as usize;

        let copy_and_last = |memory: &mut [u8]| -> Option<i32> {
            let src_end = src_addr.checked_add(copy_bytes)?;
            let dst_end = dst_addr.checked_add(copy_bytes)?;
            if src_end > memory.len() || dst_end > memory.len() {
                return None;
            }
            let same_range = src_addr == dst_addr;
            let disjoint = src_end <= dst_addr || dst_end <= src_addr;
            if !same_range && !disjoint {
                return None;
            }
            let last_offset = src_end.checked_sub(4)?;
            let last = i32::from_le_bytes([
                memory[last_offset],
                memory[last_offset + 1],
                memory[last_offset + 2],
                memory[last_offset + 3],
            ]);
            memory.copy_within(src_addr..src_end, dst_addr);
            Some(last)
        };

        let last = if let Some(result) = self
            .memory
            .with_buffer_mut_exclusive(|memory| Ok::<Option<i32>, VMError>(copy_and_last(memory)))
        {
            let Some(last) = result? else {
                return Ok(false);
            };
            last
        } else {
            let Some(last) = self
                .memory
                .with_buffer_mut(|memory| Ok::<Option<i32>, VMError>(copy_and_last(memory)))?
            else {
                return Ok(false);
            };
            last
        };

        let value_idx = base + value_slot as usize;
        if value_idx >= self.stack.len() {
            self.stack.resize(value_idx + 1, Value::Null);
        }
        self.stack[value_idx] = Value::I32(last);
        self.stack[base + i_slot as usize] = Value::I32(final_i as i32);
        if let Some(counters) = self.perf_counters.as_mut() {
            let n = iterations as u64;
            counters.super_linear_copy = counters.super_linear_copy.saturating_add(1);
            counters.i32_load = counters.i32_load.saturating_add(n);
            counters.i32_store = counters.i32_store.saturating_add(n);
            counters.memory_copy = counters.memory_copy.saturating_add(1);
            counters.memory_copy_bytes = counters.memory_copy_bytes.saturating_add(copy_bytes as u64);
        }
        if let Some(entry) = self.label_at_depth(1) {
            self.branch_to_label(1, entry);
            return Ok(true);
        }
        Ok(false)
    }

