    fn try_global_set_local_loop(
        &mut self,
        global_idx: u32,
        value_slot: u16,
        counter_slot: u16,
        end_ip: usize,
    ) -> Result<bool, VMError> {
        let frame_index = self.frames.len() - 1;
        let base = self.frames[frame_index].base;
        let count = self.stack_i32_at(base + counter_slot as usize)?;
        if count <= 0 {
            return Ok(false);
        }

        let idx = global_idx as usize;
        let val = self.stack[base + value_slot as usize].clone();
        if idx >= self.globals.len() {
            self.globals.resize(idx + 1, Value::Null);
        }
        if idx >= self.globals_assigned.len() {
            self.globals_assigned.resize(idx + 1, false);
        }
        unsafe {
            *self.globals.get_unchecked_mut(idx) = val;
            *self.globals_assigned.get_unchecked_mut(idx) = true;
        }

        self.stack[base + counter_slot as usize] = Value::I32(0);
        self.label_stack.pop();
        self.frames[frame_index].ip = end_ip.saturating_add(4);
        if let Some(counters) = self.perf_counters.as_mut() {
            let n = count as u64;
            counters.super_global_set_local_loop =
                counters.super_global_set_local_loop.saturating_add(1);
            counters.local_get = counters.local_get.saturating_add(n.saturating_mul(2));
            counters.br_if = counters.br_if.saturating_add(n);
            counters.br_if_taken = counters.br_if_taken.saturating_add(n.saturating_sub(1));
            counters.br_if_not_taken = counters.br_if_not_taken.saturating_add(1);
        }
        Ok(true)
    }

    fn try_global_set_const_loop(
        &mut self,
        global_idx: u32,
        value: i32,
        counter_slot: u16,
        end_ip: usize,
    ) -> Result<bool, VMError> {
        let frame_index = self.frames.len() - 1;
        let base = self.frames[frame_index].base;
        let count = self.stack_i32_at(base + counter_slot as usize)?;
        if count <= 0 {
            return Ok(false);
        }

        let idx = global_idx as usize;
        if idx >= self.globals.len() {
            self.globals.resize(idx + 1, Value::Null);
        }
        if idx >= self.globals_assigned.len() {
            self.globals_assigned.resize(idx + 1, false);
        }
        unsafe {
            *self.globals.get_unchecked_mut(idx) = Value::I32(value);
            *self.globals_assigned.get_unchecked_mut(idx) = true;
        }

        self.stack[base + counter_slot as usize] = Value::I32(0);
        self.label_stack.pop();
        self.frames[frame_index].ip = end_ip.saturating_add(4);
        if let Some(counters) = self.perf_counters.as_mut() {
            let n = count as u64;
            counters.super_global_set_const_loop =
                counters.super_global_set_const_loop.saturating_add(1);
            counters.local_get = counters.local_get.saturating_add(n);
            counters.br_if = counters.br_if.saturating_add(n);
            counters.br_if_taken = counters.br_if_taken.saturating_add(n.saturating_sub(1));
            counters.br_if_not_taken = counters.br_if_not_taken.saturating_add(1);
        }
        Ok(true)
    }

    fn try_struct_get_drop_loop(
        &mut self,
        obj_slot: u16,
        name_idx: u32,
        counter_slot: u16,
        end_ip: usize,
    ) -> Result<bool, VMError> {
        let frame_index = self.frames.len() - 1;
        let base = self.frames[frame_index].base;
        let count = self.stack_i32_at(base + counter_slot as usize)?;
        if count <= 0 {
            return Ok(false);
        }

        let name_value = self.get_constant(name_idx);
        let name_owned;
        let name = match &name_value {
            Value::String(s) => s.as_ref(),
            v => {
                name_owned = format!("{}", v);
                name_owned.as_str()
            }
        };
        if name == "result" {
            return Ok(false);
        }
        let getter_key = format!("__get_{}", name);
        let obj = match self.stack.get(base + obj_slot as usize) {
            Some(Value::Object(o)) => o,
            _ => return Ok(false),
        };
        let can_skip_reads = {
            if let Some(counters) = self.perf_counters.as_mut() {
                counters.record_object_lock();
            }
            let o_ref = obj.lock().unwrap();
            o_ref.properties.contains_key(name) && !o_ref.properties.contains_key(&getter_key)
        };
        if !can_skip_reads {
            return Ok(false);
        }

        self.stack[base + counter_slot as usize] = Value::I32(0);
        self.label_stack.pop();
        self.frames[frame_index].ip = end_ip.saturating_add(4);
        if let Some(counters) = self.perf_counters.as_mut() {
            let n = count as u64;
            counters.super_struct_get_drop_loop =
                counters.super_struct_get_drop_loop.saturating_add(1);
            counters.local_get = counters.local_get.saturating_add(n.saturating_mul(2));
            counters.br_if = counters.br_if.saturating_add(n);
            counters.br_if_taken = counters.br_if_taken.saturating_add(n.saturating_sub(1));
            counters.br_if_not_taken = counters.br_if_not_taken.saturating_add(1);
        }
        Ok(true)
    }

    fn try_struct_get_local_loop(
        &mut self,
        obj_slot: u16,
        name_idx: u32,
        dst_slot: u16,
        counter_slot: u16,
        end_ip: usize,
    ) -> Result<bool, VMError> {
        if dst_slot == obj_slot || dst_slot == counter_slot {
            return Ok(false);
        }
        let frame_index = self.frames.len() - 1;
        let base = self.frames[frame_index].base;
        let count = self.stack_i32_at(base + counter_slot as usize)?;
        if count <= 0 {
            return Ok(false);
        }

        let name_value = self.get_constant(name_idx);
        let name_owned;
        let name = match &name_value {
            Value::String(s) => s.as_ref(),
            v => {
                name_owned = format!("{}", v);
                name_owned.as_str()
            }
        };
        if name == "result" {
            return Ok(false);
        }
        let getter_key = format!("__get_{}", name);
        let obj = match self.stack.get(base + obj_slot as usize) {
            Some(Value::Object(o)) => o,
            _ => return Ok(false),
        };
        let value = {
            if let Some(counters) = self.perf_counters.as_mut() {
                counters.record_object_lock();
            }
            let o_ref = obj.lock().unwrap();
            if o_ref.properties.contains_key(&getter_key) {
                return Ok(false);
            }
            match o_ref.properties.get(name) {
                Some(value) => value.clone(),
                None => return Ok(false),
            }
        };

        let dst_index = base + dst_slot as usize;
        if dst_index >= self.stack.len() {
            return Ok(false);
        }
        self.stack[dst_index] = value;
        self.stack[base + counter_slot as usize] = Value::I32(0);
        self.label_stack.pop();
        self.frames[frame_index].ip = end_ip.saturating_add(4);
        if let Some(counters) = self.perf_counters.as_mut() {
            let n = count as u64;
            counters.super_struct_get_local_loop =
                counters.super_struct_get_local_loop.saturating_add(1);
            counters.local_get = counters.local_get.saturating_add(n.saturating_mul(2));
            counters.local_set = counters.local_set.saturating_add(n);
            counters.br_if = counters.br_if.saturating_add(n);
            counters.br_if_taken = counters.br_if_taken.saturating_add(n.saturating_sub(1));
            counters.br_if_not_taken = counters.br_if_not_taken.saturating_add(1);
        }
        Ok(true)
    }

